//! Source maps for a development build (docs/design/backend.md §11): one
//! Source Map v3 file (ECMA-426) per emitted module, `Main.mjs.map` beside
//! `Main.mjs`.
//!
//! **Recorded in the print pass, encoded after it.** The printer appends a
//! `Mapping` — the generated BYTE offset it is about to write at and the
//! node's source byte offset — at every statement and every expression whose
//! `JsIr` node carries a position (`Print.Printer.mark`); no second walk of
//! the tree. `write` then turns the byte offsets into the format's
//! line/column pairs in ONE forward scan of the printed bytes, since the
//! marks arrive in generated order, and a binary search of the module's line
//! table per mark for the source side. Both columns are in UTF-16 code
//! units, which is what the format counts (ECMA-426 §4) and what a browser
//! means by a column; ASCII, which is nearly every byte either side, costs
//! one compare per byte.
//!
//! The map holds the module's `.beni` text in `sourcesContent`, so a browser
//! shows the source without fetching it — `beni serve` serves `--out` and
//! nothing above it — and `names` holds a declaration's beni name where the
//! printed one is `Module$base`.

const std = @import("std");
const builtin = @import("builtin");
const Allocator = std.mem.Allocator;
const InternPool = @import("../InternPool.zig");

/// One recorded position: where the printer was in its output, and where
/// the node it was about to print came from.
pub const Mapping = struct {
    /// Byte offset into the printed module.
    generated: u32,
    /// Byte offset into the module's `.beni` source.
    source: u32,
    /// The beni name a binding written here had: an index into
    /// `Marks.names`, or `no_name`.
    name: u32 = no_name,

    pub const no_name = std.math.maxInt(u32);
};

/// What the printer appends to. In the printer's scratch arena.
pub const Marks = struct {
    list: std.ArrayList(Mapping) = .empty,
    /// The map's `names`, in first-use order. The printer numbers them by
    /// its own name column, so two locals both written `x` are two entries.
    names: std.ArrayList(InternPool.Symbol) = .empty,
    allocator: Allocator,

    pub fn init(allocator: Allocator) Marks {
        return .{ .allocator = allocator };
    }

    /// Record `source` at `generated`. Nested nodes often start at the same
    /// byte — a call and its callee, a binary and its left operand — and
    /// the innermost, recorded last, is kept: the format allows one segment
    /// per generated column, and the innermost is the token the reader sees
    /// first there (`a * b` starts at `a`, not at the `*` the binary is
    /// positioned on).
    pub fn add(m: *Marks, generated: usize, source: u32, name: u32) Allocator.Error!void {
        const at: u32 = @intCast(generated);
        if (m.list.items.len != 0) {
            const last = &m.list.items[m.list.items.len - 1];
            std.debug.assert(last.generated <= at);
            if (last.generated == at) {
                last.* = .{ .generated = at, .source = source, .name = if (name == Mapping.no_name) last.name else name };
                return;
            }
        }
        try m.list.append(m.allocator, .{ .generated = at, .source = source, .name = name });
    }

    /// The compact printer's adjacency guard is about to write a space at
    /// byte `space`. A mark recorded there is for the token after the
    /// space, so it moves past it (backend.md §11.2, *What the marks
    /// survive*, item 3).
    pub fn skipSpace(m: *Marks, space: usize) void {
        if (m.list.items.len == 0) return;
        const last = &m.list.items[m.list.items.len - 1];
        if (last.generated == space) last.generated += 1;
    }

    /// The printer took its bytes back to `length` (a `;` before a `}`). A
    /// mark past it was for a node that printed nothing.
    pub fn dropPast(m: *Marks, length: usize) void {
        while (m.list.items.len != 0 and m.list.items[m.list.items.len - 1].generated > length) m.list.items.len -= 1;
    }
};

/// How a `Mapping.name` becomes text: `Print.Names`, without the import.
pub const NameText = struct {
    context: *const anyopaque,
    lookup: *const fn (context: *const anyopaque, symbol: InternPool.Symbol) []const u8,
};

pub const Input = struct {
    /// The generated file's name, as the map's `file` (`Main.mjs`).
    file: []const u8,
    /// The source's URL relative to the map (`../src/Main.beni`).
    source_url: []const u8,
    /// The module's `.beni` text, for `sourcesContent`.
    source: []const u8,
    /// The source's line table: `line_starts[l]` is the byte offset of
    /// 0-based line `l`.
    line_starts: []const u32,
    /// The printed module.
    generated: []const u8,
    /// In generated order.
    mappings: []const Mapping,
    /// `Marks.names`, and how a name becomes text.
    names: []const InternPool.Symbol,
    name_text: NameText,
};

/// The map's bytes, a JSON object and a newline, from `gpa`. Everything
/// else comes from `scratch`. One module, one source: a development build's
/// map, and a release build's in the multi-file layout (backend.md §11.1,
/// §11.2).
pub fn write(gpa: Allocator, scratch: Allocator, in: Input) Allocator.Error![]u8 {
    const names = try scratch.alloc([]const u8, in.names.len);
    for (names, in.names) |*text, symbol| text.* = in.name_text.lookup(in.name_text.context, symbol);
    return writeJoined(gpa, scratch, .{
        .file = in.file,
        .generated = in.generated,
        .sources = &.{.{ .url = in.source_url, .text = in.source, .line_starts = in.line_starts }},
        .stretches = &.{.{ .start = 0, .source = 0, .mappings = in.mappings, .names = names }},
    });
}

/// One entry of a map's `sources`: a `.beni` module.
pub const Source = struct {
    /// Its URL relative to the map (`../src/Main.beni`).
    url: []const u8,
    /// Its text, for `sourcesContent`.
    text: []const u8,
    /// Its line table: `line_starts[l]` is the byte offset of 0-based line
    /// `l`.
    line_starts: []const u32,
};

/// A stretch of the generated file, from `start` to the next stretch's
/// (backend.md §11.2, *The join*): one module of a scope-hoisted file, or
/// bytes no beni line wrote.
pub const Stretch = struct {
    /// Byte offset into the generated file.
    start: u32,
    /// Index into `Joined.sources`, or `unmapped`.
    source: u32,
    /// Relative to `start`, in generated order.
    mappings: []const Mapping = &.{},
    /// The stretch's names, by `Mapping.name`.
    names: []const []const u8 = &.{},

    pub const unmapped = std.math.maxInt(u32);
};

pub const Joined = struct {
    /// The generated file's name, as the map's `file` (`_main.mjs`).
    file: []const u8,
    /// The printed file.
    generated: []const u8,
    sources: []const Source,
    /// Ascending by `start`; the first need not start at 0, and bytes
    /// before it are unmapped.
    stretches: []const Stretch,
};

/// The map of a file joined from stretches (backend.md §11.2): one entry in
/// `sources` per module, each stretch's marks moved by its start, its names
/// numbered after the stretches' before it, and a one-field segment where
/// an unmapped stretch begins after a mapped one on its line.
pub fn writeJoined(gpa: Allocator, scratch: Allocator, in: Joined) Allocator.Error![]u8 {
    var out: std.ArrayList(u8) = .empty;
    var reserve: usize = 128;
    for (in.sources) |s| reserve += s.url.len + s.text.len + 4;
    for (in.stretches) |s| reserve += s.mappings.len * 6;
    try out.ensureTotalCapacity(scratch, reserve);
    try out.appendSlice(scratch, "{\"version\":3,\"file\":");
    try jsonString(scratch, &out, in.file);
    try out.appendSlice(scratch, ",\"sources\":[");
    for (in.sources, 0..) |s, i| {
        if (i != 0) try out.append(scratch, ',');
        try jsonString(scratch, &out, s.url);
    }
    try out.appendSlice(scratch, "],\"sourcesContent\":[");
    for (in.sources, 0..) |s, i| {
        if (i != 0) try out.append(scratch, ',');
        try jsonString(scratch, &out, s.text);
    }
    try out.appendSlice(scratch, "],\"names\":[");
    var first = true;
    for (in.stretches) |s| for (s.names) |text| {
        if (!first) try out.append(scratch, ',');
        first = false;
        try jsonString(scratch, &out, text);
    };
    try out.appendSlice(scratch, "],\"mappings\":\"");
    try encodeMappings(scratch, &out, in);
    try out.appendSlice(scratch, "\"}\n");
    return gpa.dupe(u8, out.items);
}

/// The `mappings` string: `;` between generated lines, `,` between
/// segments, each segment the VLQ deltas of generated column, source index,
/// source line, source column and, when there is one, name index — or, for
/// an unmapped stretch, the generated column alone.
fn encodeMappings(
    scratch: Allocator,
    out: *std.ArrayList(u8),
    in: Joined,
) Allocator.Error!void {
    var e: Encoder = .{ .out = out, .scratch = scratch, .generated = in.generated };
    const lines = try scratch.alloc(?SourceLines, in.sources.len);
    @memset(lines, null);
    var name_base: u32 = 0;
    for (in.stretches, 0..) |s, k| {
        const last = k + 1 == in.stretches.len;
        const end: usize = if (last) in.generated.len else in.stretches[k + 1].start;
        defer name_base += @intCast(s.names.len);
        // An unmapped stretch, or the bytes of a mapped one before its
        // first mark: what the segment before them says is not about them.
        const first: usize = if (s.source == Stretch.unmapped or s.mappings.len == 0)
            end
        else
            @as(usize, s.start) + s.mappings[0].generated;
        if (first > s.start and s.start < end) try e.unmapped(s.start);
        if (s.source == Stretch.unmapped) continue;
        const source = &lines[s.source];
        if (source.* == null) source.* = try .init(scratch, in.sources[s.source].text, in.sources[s.source].line_starts);
        for (s.mappings) |m| {
            const target = @as(usize, s.start) + m.generated;
            // The join drops a module's last newline, and nothing maps to
            // what it leaves past the stretch.
            if (!last and target >= end) break;
            try e.advance(@min(target, in.generated.len));
            const name = if (m.name == Mapping.no_name) Mapping.no_name else m.name + name_base;
            try e.segment(s.source, source.*.?.position(m.source), name);
        }
    }
}

/// `encodeMappings`' cursor and the previous segment's fields, which the
/// next one's deltas are against.
const Encoder = struct {
    out: *std.ArrayList(u8),
    scratch: Allocator,
    generated: []const u8,
    /// The generated cursor: byte offset and UTF-16 column.
    at: usize = 0,
    column: u32 = 0,
    // What the previous segment wrote, for the deltas. The column resets per
    // generated line; the rest run across the whole file.
    prev_column: i64 = 0,
    prev_source: i64 = 0,
    prev_source_line: i64 = 0,
    prev_source_column: i64 = 0,
    prev_name: i64 = 0,
    segment_on_line: bool = false,
    /// Whether the line's last segment maps somewhere.
    mapped: bool = false,

    /// Move the cursor to byte `target`, writing a `;` for every line it
    /// passes the end of.
    fn advance(e: *Encoder, target: usize) Allocator.Error!void {
        const generated = e.generated;
        var at = e.at;
        var column = e.column;
        defer {
            e.at = at;
            e.column = column;
        }
        while (at < target) {
            // Sixteen bytes at a time while they are plain ASCII on one line,
            // which is nearly all of a printed module.
            if (use_blocks and target - at >= block) {
                const v: Block = generated[at..][0..block].*;
                const special = (v >= @as(Block, @splat(0x80))) | (v == @as(Block, @splat('\n'))) | (v == @as(Block, @splat('\r')));
                if (!@reduce(.Or, special)) {
                    at += block;
                    column += block;
                    continue;
                }
            }
            // Eight at a time in one word where the vectors would loop.
            if (!use_blocks and target - at >= word) {
                const x = loadWord(generated, at);
                if (x & highs == 0 and !hasByte(x, '\n') and !hasByte(x, '\r')) {
                    at += word;
                    column += word;
                    continue;
                }
            }
            const c = generated[at];
            if (c < 0x80) {
                at += 1;
                if (c == '\n' or (c == '\r' and (at >= generated.len or generated[at] != '\n'))) {
                    try e.newLine();
                    column = 0;
                } else column += 1;
                continue;
            }
            // U+2028 and U+2029 end a line in JavaScript.
            if (c == 0xE2 and at + 2 < generated.len and generated[at + 1] == 0x80 and
                (generated[at + 2] == 0xA8 or generated[at + 2] == 0xA9))
            {
                at += 3;
                try e.newLine();
                column = 0;
                continue;
            }
            column += utf16Units(c);
            at += 1;
        }
    }

    fn newLine(e: *Encoder) Allocator.Error!void {
        try e.out.append(e.scratch, ';');
        e.prev_column = 0;
        e.segment_on_line = false;
        e.mapped = false;
    }

    /// A segment at the cursor mapping to `s` in source `source`, or none
    /// when it would repeat the one before it on the line.
    fn segment(e: *Encoder, source: u32, s: Position, name: u32) Allocator.Error!void {
        if (e.segment_on_line and e.mapped and source == e.prev_source and s.line == e.prev_source_line and
            s.column == e.prev_source_column and name == Mapping.no_name) return;
        // One capacity check per segment: a comma and five fields.
        try e.out.ensureUnusedCapacity(e.scratch, 1 + 5 * max_vlq_digits);
        if (e.segment_on_line) e.out.appendAssumeCapacity(',');
        vlqAssumeCapacity(e.out, @as(i64, e.column) - e.prev_column);
        e.prev_column = e.column;
        vlqAssumeCapacity(e.out, @as(i64, source) - e.prev_source);
        e.prev_source = source;
        vlqAssumeCapacity(e.out, s.line - e.prev_source_line);
        e.prev_source_line = s.line;
        vlqAssumeCapacity(e.out, s.column - e.prev_source_column);
        e.prev_source_column = s.column;
        if (name != Mapping.no_name) {
            vlqAssumeCapacity(e.out, @as(i64, name) - e.prev_name);
            e.prev_name = name;
        }
        e.segment_on_line = true;
        e.mapped = true;
    }

    /// A one-field segment at byte `at`: what follows maps nowhere. Only
    /// after a mapped segment on the same line, since a line starts
    /// unmapped.
    fn unmapped(e: *Encoder, at: usize) Allocator.Error!void {
        try e.advance(@min(at, e.generated.len));
        if (!e.segment_on_line or !e.mapped) return;
        try e.out.ensureUnusedCapacity(e.scratch, 1 + max_vlq_digits);
        e.out.appendAssumeCapacity(',');
        vlqAssumeCapacity(e.out, @as(i64, e.column) - e.prev_column);
        e.prev_column = e.column;
        e.mapped = false;
    }
};

const block = 16;
const Block = @Vector(block, u8);

/// Whether the two scans below skip sixteen bytes at a time. Only where
/// LLVM compiles them: Zig's own backend writes a vector operation as a
/// loop over its lanes, so a block cost thousands of instructions where
/// sixteen bytes one at a time cost a hundred — a third of a development
/// build of a page was its maps' `sourcesContent`. The two paths find the
/// same bytes; only how fast they skip the ones that need nothing differs.
const use_blocks = builtin.zig_backend == .stage2_llvm;

// Where it does not, the scans skip eight bytes at a time in one `u64`
// instead: a few integer operations decide whether any of the eight is one
// the scan must look at, exactly — the tests below are the classic
// zero-byte tests, which never answer yes for a word with no such byte and
// never no for one with one.
const word = 8;
const ones: u64 = 0x0101010101010101;
const highs: u64 = 0x8080808080808080;

/// The eight bytes at `at`, in one load.
inline fn loadWord(bytes: []const u8, at: usize) u64 {
    return @as(*align(1) const u64, @ptrCast(bytes[at..][0..word])).*;
}

/// Whether some byte of `x` is `b`.
inline fn hasByte(x: u64, comptime b: u8) bool {
    const y = x ^ (ones * b);
    return (y -% ones) & ~y & highs != 0;
}

/// Whether some byte of `x` is below `n`, which is at most 128.
inline fn hasBelow(x: u64, comptime n: u8) bool {
    comptime std.debug.assert(n <= 128);
    return (x -% ones * n) & ~x & highs != 0;
}

/// UTF-16 code units for a UTF-8 lead byte: two for a four-byte sequence,
/// none for a continuation byte, one otherwise.
inline fn utf16Units(c: u8) u32 {
    if (c & 0xC0 == 0x80) return 0;
    return if (c >= 0xF0) 2 else 1;
}

const Position = struct { line: i64, column: i64 };

/// The source side: 0-based line and UTF-16 column of a byte offset.
///
/// A column is a byte difference less what the bytes past ASCII before it
/// on its line take back: every such byte is listed once, with the running
/// total of `1 - utf16Units` up to it (`shrink`), so a column is two binary
/// searches whatever order the marks come in — one line of 4 097 marks, the
/// generated order jumping back and forth along it, costs no rescan. An
/// all-ASCII source lists nothing and a column is the byte difference.
const SourceLines = struct {
    source: []const u8,
    line_starts: []const u32,
    /// The offset of every byte past ASCII, ascending.
    wide: []const u32,
    /// `shrink[i]`: the bytes `wide[0..i + 1]` count more than the UTF-16
    /// units they make. A running total can dip below zero inside a
    /// four-byte sequence, whose lead byte makes two units.
    shrink: []const i32,
    /// `line_wide[l]`: the first `wide` at or past `line_starts[l]`, and
    /// `wide.len` last — so a column's search is over its line's few.
    line_wide: []const u32,
    /// The line of the last offset asked about.
    hint: usize = 0,

    fn init(scratch: Allocator, source: []const u8, line_starts: []const u32) Allocator.Error!SourceLines {
        var count: usize = 0;
        var i: usize = 0;
        while (i < source.len) {
            if (source.len - i >= word and loadWord(source, i) & highs == 0) {
                i += word;
                continue;
            }
            count += @intFromBool(source[i] >= 0x80);
            i += 1;
        }
        const wide = try scratch.alloc(u32, count);
        const shrink = try scratch.alloc(i32, count);
        var k: usize = 0;
        var total: i32 = 0;
        i = 0;
        while (i < source.len) {
            if (source.len - i >= word and loadWord(source, i) & highs == 0) {
                i += word;
                continue;
            }
            const c = source[i];
            if (c >= 0x80) {
                total += 1 - @as(i32, @intCast(utf16Units(c)));
                wide[k] = @intCast(i);
                shrink[k] = total;
                k += 1;
            }
            i += 1;
        }
        // Each line's first, by a walk alongside `wide` while the lines
        // ascend, as the lexer makes them; a search where one does not.
        const line_wide = try scratch.alloc(u32, line_starts.len + 1);
        var at: usize = 0;
        for (line_starts, 0..) |start, l| {
            if (l != 0 and start < line_starts[l - 1]) at = lowerBound(wide, 0, wide.len, start) else {
                while (at < wide.len and wide[at] < start) at += 1;
            }
            line_wide[l] = @intCast(at);
        }
        line_wide[line_starts.len] = @intCast(wide.len);
        return .{ .source = source, .line_starts = line_starts, .wide = wide, .shrink = shrink, .line_wide = line_wide };
    }

    /// `std.sort.lowerBound` over `wide[lo..hi]`, written out: the first at
    /// or past `offset`. The generic search's comparator is a call per step
    /// where Zig's own backend compiles the compiler.
    fn lowerBound(wide: []const u32, from: usize, to: usize, offset: usize) usize {
        var lo = from;
        var hi = to;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (wide[mid] < offset) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    /// What the bytes past ASCII before `offset` take back from a column,
    /// `offset` on 0-based line `line` or clamped to the source's end: the
    /// first `wide` at or past it is among the line's (`line_wide`), the
    /// search over every one narrowed to them.
    fn shrinkBefore(s: *const SourceLines, line: usize, offset: usize) i64 {
        const lo = lowerBound(s.wide, s.line_wide[line], s.line_wide[line + 1], offset);
        return if (lo == 0) 0 else s.shrink[lo - 1];
    }

    /// Whether `offset` is on 0-based line `line`.
    fn within(s: *const SourceLines, line: usize, offset: u32) bool {
        if (line >= s.line_starts.len or s.line_starts[line] > offset) return false;
        return line + 1 == s.line_starts.len or offset < s.line_starts[line + 1];
    }

    fn position(s: *SourceLines, offset: u32) Position {
        if (s.line_starts.len == 0) return .{ .line = 0, .column = 0 };
        // The line of the mark before, or the one after it, nearly always:
        // marks follow the source within a declaration.
        var lo: usize = s.hint;
        if (!s.within(lo, offset)) {
            lo += 1;
            if (!s.within(lo, offset)) {
                lo = 0;
                var hi: usize = s.line_starts.len;
                while (hi - lo > 1) {
                    const mid = lo + (hi - lo) / 2;
                    if (s.line_starts[mid] <= offset) lo = mid else hi = mid;
                }
            }
        }
        s.hint = lo;
        const start = @min(@as(usize, s.line_starts[lo]), s.source.len);
        const end = @max(start, @min(@as(usize, offset), s.source.len));
        const bytes: i64 = @intCast(end - start);
        if (s.wide.len == 0) return .{ .line = @intCast(lo), .column = bytes };
        return .{ .line = @intCast(lo), .column = bytes - (s.shrinkBefore(lo, end) - s.shrinkBefore(lo, start)) };
    }
};

const base64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/// One Base64 VLQ: the sign in the lowest bit, five bits per digit, the
/// sixth bit set on every digit but the last.
fn vlq(scratch: Allocator, out: *std.ArrayList(u8), value: i64) Allocator.Error!void {
    try out.ensureUnusedCapacity(scratch, max_vlq_digits);
    vlqAssumeCapacity(out, value);
}

/// A 64-bit value with its sign bit takes at most 13 five-bit digits.
const max_vlq_digits = 13;

fn vlqAssumeCapacity(out: *std.ArrayList(u8), value: i64) void {
    var v: u64 = if (value < 0) (@as(u64, @intCast(-value)) << 1) | 1 else @as(u64, @intCast(value)) << 1;
    // The digits are written in place: `appendAssumeCapacity` is two calls
    // where Zig's own backend compiles the compiler.
    std.debug.assert(out.capacity - out.items.len >= max_vlq_digits);
    var len = out.items.len;
    defer out.items.len = len;
    // The common case, a delta under 16 either way: one digit.
    if (v < 32) {
        out.items.ptr[len] = base64[@intCast(v)];
        len += 1;
        return;
    }
    while (true) {
        var digit: u8 = @intCast(v & 31);
        v >>= 5;
        if (v != 0) digit |= 32;
        out.items.ptr[len] = base64[digit];
        len += 1;
        if (v == 0) return;
    }
}

/// `ArrayList.appendSliceAssumeCapacity`, without its calls.
inline fn appendAssumeCapacity(out: *std.ArrayList(u8), bytes: []const u8) void {
    const len = out.items.len;
    out.items.len = len + bytes.len;
    @memcpy(out.items[len..][0..bytes.len], bytes);
}

/// `text` as a JSON string: `"`, `\` and the control characters escaped,
/// everything else — UTF-8 included — as it is.
fn jsonString(scratch: Allocator, out: *std.ArrayList(u8), text: []const u8) Allocator.Error!void {
    try out.append(scratch, '"');
    var run: usize = 0;
    var i: usize = 0;
    while (i < text.len) : (i += 1) {
        // Sixteen bytes at a time while none needs an escape.
        while (use_blocks and text.len - i >= block) {
            const v: Block = text[i..][0..block].*;
            const special = (v < @as(Block, @splat(0x20))) | (v == @as(Block, @splat('"'))) | (v == @as(Block, @splat('\\')));
            if (@reduce(.Or, special)) break;
            i += block;
        }
        // Eight at a time in one word where the vectors would loop.
        while (!use_blocks and text.len - i >= word) {
            const x = loadWord(text, i);
            if (hasBelow(x, 0x20) or hasByte(x, '"') or hasByte(x, '\\')) break;
            i += word;
        }
        if (i == text.len) break;
        const c = text[i];
        if (c >= 0x20 and c != '"' and c != '\\') continue;
        // The run before the escape and the escape, in one reservation and
        // two copies: a source's every line ends in one.
        try out.ensureUnusedCapacity(scratch, i - run + 6);
        appendAssumeCapacity(out, text[run..i]);
        run = i + 1;
        switch (c) {
            '"' => appendAssumeCapacity(out, "\\\""),
            '\\' => appendAssumeCapacity(out, "\\\\"),
            '\n' => appendAssumeCapacity(out, "\\n"),
            '\r' => appendAssumeCapacity(out, "\\r"),
            '\t' => appendAssumeCapacity(out, "\\t"),
            else => {
                var buf: [6]u8 = undefined;
                appendAssumeCapacity(out, std.fmt.bufPrint(&buf, "\\u{x:0>4}", .{c}) catch unreachable);
            },
        }
    }
    try out.appendSlice(scratch, text[run..]);
    try out.append(scratch, '"');
}

/// The URL of `source_path` relative to the directory of the map at
/// `map_path`, both absolute and lexically normal (`/`-separated, no `.`
/// or `..` segment). A path that shares no directory with the map's climbs
/// to the root.
pub fn relativeUrl(scratch: Allocator, map_path: []const u8, source_path: []const u8) Allocator.Error![]const u8 {
    const map_dir = std.fs.path.dirnamePosix(map_path) orelse "";
    var from = std.mem.tokenizeScalar(u8, map_dir, '/');
    var to = std.mem.tokenizeScalar(u8, source_path, '/');
    var from_rest: ?[]const u8 = null;
    var to_rest: ?[]const u8 = null;
    while (true) {
        from_rest = from.next();
        to_rest = to.next();
        const a = from_rest orelse break;
        const b = to_rest orelse break;
        if (!std.mem.eql(u8, a, b)) break;
    }
    var out: std.ArrayList(u8) = .empty;
    if (from_rest != null) {
        try out.appendSlice(scratch, "../");
        while (from.next() != null) try out.appendSlice(scratch, "../");
    }
    if (to_rest) |first| {
        try out.appendSlice(scratch, first);
        while (to.next()) |segment| {
            try out.append(scratch, '/');
            try out.appendSlice(scratch, segment);
        }
    }
    return out.items;
}

/// `path` made absolute against `cwd` (itself absolute) and lexically
/// normal: `.` segments dropped, `..` taking the segment before it.
pub fn absolute(scratch: Allocator, cwd: []const u8, path: []const u8) Allocator.Error![]const u8 {
    var segments: std.ArrayList([]const u8) = .empty;
    const parts: [2][]const u8 = .{ if (std.fs.path.isAbsolutePosix(path)) "" else cwd, path };
    for (parts) |part| {
        var it = std.mem.tokenizeScalar(u8, part, '/');
        while (it.next()) |segment| {
            if (std.mem.eql(u8, segment, ".")) continue;
            if (std.mem.eql(u8, segment, "..")) {
                _ = segments.pop();
                continue;
            }
            try segments.append(scratch, segment);
        }
    }
    var out: std.ArrayList(u8) = .empty;
    for (segments.items) |segment| {
        try out.append(scratch, '/');
        try out.appendSlice(scratch, segment);
    }
    if (out.items.len == 0) try out.append(scratch, '/');
    return out.items;
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

const testing = std.testing;

fn expectVlq(expected: []const u8, value: i64) !void {
    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(testing.allocator);
    try vlq(testing.allocator, &out, value);
    try testing.expectEqualStrings(expected, out.items);
}

test "a VLQ digit carries five bits and the sign rides in the lowest" {
    try expectVlq("A", 0);
    try expectVlq("C", 1);
    try expectVlq("D", -1);
    try expectVlq("e", 15);
    try expectVlq("gB", 16);
    try expectVlq("hB", -16);
    try expectVlq("2H", 123);
    try expectVlq("+8D", 1999);
}

test "the word tests find a byte exactly when one of the eight is it" {
    // Every byte value in every lane, among neighbours that are and are not
    // special themselves, against a byte at a time.
    var prng: std.Random.DefaultPrng = .init(0x5eed);
    const random = prng.random();
    for (0..word) |lane| for (0..256) |value| for (0..8) |_| {
        var bytes: [word]u8 = undefined;
        random.bytes(&bytes);
        bytes[lane] = @intCast(value);
        const x = loadWord(&bytes, 0);
        var nl = false;
        var quote = false;
        var low = false;
        for (bytes) |b| {
            nl = nl or b == '\n';
            quote = quote or b == '"';
            low = low or b < 0x20;
        }
        try testing.expectEqual(nl, hasByte(x, '\n'));
        try testing.expectEqual(quote, hasByte(x, '"'));
        try testing.expectEqual(low, hasBelow(x, 0x20));
    };
}

test "a source URL is relative to the map's directory" {
    var a: std.heap.ArenaAllocator = .init(testing.allocator);
    defer a.deinit();
    const arena = a.allocator();
    try testing.expectEqualStrings("../src/Main.beni", try relativeUrl(arena, "/p/out/Main.mjs.map", "/p/src/Main.beni"));
    try testing.expectEqualStrings("../../src/A/B.beni", try relativeUrl(arena, "/p/out/A/B.mjs.map", "/p/src/A/B.beni"));
    try testing.expectEqualStrings("Main.beni", try relativeUrl(arena, "/p/Main.mjs.map", "/p/Main.beni"));
    try testing.expectEqualStrings("../x/Main.beni", try relativeUrl(arena, "/a/Main.mjs.map", "/x/Main.beni"));
    try testing.expectEqualStrings("/p/x", try absolute(arena, "/p/q", "../x"));
    try testing.expectEqualStrings("/p/q/src/A.beni", try absolute(arena, "/p/q", "./src/A.beni"));
    try testing.expectEqualStrings("/abs/A.beni", try absolute(arena, "/p", "/abs/A.beni"));
}

test "columns count UTF-16 units on both sides, and a line ends at U+2028" {
    var a: std.heap.ArenaAllocator = .init(testing.allocator);
    defer a.deinit();
    const arena = a.allocator();
    // Generated: `"é😀";x` then U+2028 then `y`. Source: `é😀 z`.
    const generated = "\"\xc3\xa9\xf0\x9f\x98\x80\";x\xe2\x80\xa8y";
    const source = "\xc3\xa9\xf0\x9f\x98\x80 z";
    const nothing = struct {
        fn f(_: *const anyopaque, _: InternPool.Symbol) []const u8 {
            return "";
        }
    }.f;
    const text = try write(arena, arena, .{
        .file = "M.mjs",
        .source_url = "M.beni",
        .source = source,
        .line_starts = &.{0},
        .generated = generated,
        // `x` is at UTF-16 column 6 (`"`, é, two for 😀, `"`, `;`); `z` at 4.
        .mappings = &.{
            .{ .generated = 9, .source = 7 },
            .{ .generated = 13, .source = 0 },
        },
        .names = &.{},
        .name_text = .{ .context = undefined, .lookup = nothing },
    });
    try testing.expectEqualStrings(
        "{\"version\":3,\"file\":\"M.mjs\",\"sources\":[\"M.beni\"],\"sourcesContent\":[\"\xc3\xa9\xf0\x9f\x98\x80 z\"],\"names\":[],\"mappings\":\"MAAI;AAAJ\"}\n",
        text,
    );
}

test "a source column is right whatever order the marks on its line come in" {
    // `λa → b`: `b` is UTF-16 column 5 and `a` column 1. The marks come
    // right to left, which once made each one rescan the line from its
    // start.
    var a: std.heap.ArenaAllocator = .init(testing.allocator);
    defer a.deinit();
    const arena = a.allocator();
    const nothing = struct {
        fn f(_: *const anyopaque, _: InternPool.Symbol) []const u8 {
            return "";
        }
    }.f;
    const text = try write(arena, arena, .{
        .file = "M.mjs",
        .source_url = "M.beni",
        .source = "λa → b",
        .line_starts = &.{0},
        .generated = "xy",
        .mappings = &.{
            .{ .generated = 0, .source = 8 },
            .{ .generated = 1, .source = 2 },
        },
        .names = &.{},
        .name_text = .{ .context = undefined, .lookup = nothing },
    });
    try testing.expect(std.mem.endsWith(u8, text, "\"mappings\":\"AAAK,CAAJ\"}\n"));
}

test "a joined map moves each stretch's marks, numbers its names after the ones before, and leaves the rest unmapped" {
    // `backend.md` §11.2, *The join*. Generated: `ab;` from the first source,
    // `HAND;` that no beni line wrote, `cd` from the second. The first
    // stretch's mark at its end marks the stretch after it and records
    // nothing; the third's first mark is not at its start, but what comes
    // before it is already unmapped, so no segment is needed there.
    var a: std.heap.ArenaAllocator = .init(testing.allocator);
    defer a.deinit();
    const arena = a.allocator();
    const text = try writeJoined(arena, arena, .{
        .file = "_main.mjs",
        .generated = "ab;HAND;cd\n",
        .sources = &.{
            .{ .url = "A.beni", .text = "x = 1", .line_starts = &.{0} },
            .{ .url = "B.beni", .text = "\nlet y", .line_starts = &.{ 0, 1 } },
        },
        .stretches = &.{
            .{ .start = 0, .source = 0, .names = &.{"x"}, .mappings = &.{
                .{ .generated = 0, .source = 0, .name = 0 },
                .{ .generated = 1, .source = 2 },
                .{ .generated = 3, .source = 4 },
            } },
            .{ .start = 3, .source = Stretch.unmapped },
            .{ .start = 8, .source = 1, .names = &.{"y"}, .mappings = &.{
                .{ .generated = 1, .source = 4, .name = 0 },
            } },
        },
    });
    try testing.expectEqualStrings(
        "{\"version\":3,\"file\":\"_main.mjs\",\"sources\":[\"A.beni\",\"B.beni\"],\"sourcesContent\":[\"x = 1\",\"\\nlet y\"],\"names\":[\"x\",\"y\"],\"mappings\":\"AAAAA,CAAE,E,MCCCC\"}\n",
        text,
    );
}

test "a mapped stretch whose first mark is past its start begins unmapped" {
    // The bytes before the first mark of a module are not about the
    // module before it: `;` and the column of `b`'s stretch get a
    // one-field segment, and `c` maps.
    var a: std.heap.ArenaAllocator = .init(testing.allocator);
    defer a.deinit();
    const arena = a.allocator();
    const text = try writeJoined(arena, arena, .{
        .file = "m.mjs",
        .generated = "a;bc",
        .sources = &.{.{ .url = "A.beni", .text = "abc", .line_starts = &.{0} }},
        .stretches = &.{
            .{ .start = 0, .source = 0, .mappings = &.{.{ .generated = 0, .source = 0 }} },
            .{ .start = 2, .source = 0, .mappings = &.{.{ .generated = 1, .source = 2 }} },
        },
    });
    try testing.expect(std.mem.endsWith(u8, text, "\"mappings\":\"AAAA,E,CAAE\"}\n"));
}

test "a mark the guard's space separates from its token moves past the space" {
    var a: std.heap.ArenaAllocator = .init(testing.allocator);
    defer a.deinit();
    var marks: Marks = .init(a.allocator());
    try marks.add(3, 10, Mapping.no_name);
    marks.skipSpace(2);
    try testing.expectEqual(@as(u32, 3), marks.list.items[0].generated);
    marks.skipSpace(3);
    try testing.expectEqual(@as(u32, 4), marks.list.items[0].generated);
    try marks.add(9, 11, Mapping.no_name);
    marks.dropPast(9);
    try testing.expectEqual(@as(usize, 2), marks.list.items.len);
    marks.dropPast(8);
    try testing.expectEqual(@as(usize, 1), marks.list.items.len);
}
